INSERT INTO `equipment` VALUES (1,'CAM-001','Canon EOS R50','CAMERA','24.2 MP mirrorless camera with an 18-45mm kit lens. Includes a battery, charger and carry bag.','Media Lab, Level 2',NULL,'READY',0,'2026-10-28 17:04:42.377215'),(2,'CAM-002','Sony A6400','CAMERA','Compact mirrorless camera for photography and video projects. Includes a 16-50mm lens and spare battery.','Media Lab, Level 2',NULL,'READY',0,'2026-10-28 17:04:42.391214'),(3,'CAM-003','DJI Osmo Pocket 3','CAMERA','Pocket camera with a built-in three-axis stabilizer. Supplied with a protective cover and USB-C cable.','Media Lab, Level 2',NULL,'READY',0,'2026-10-28 17:04:42.393716'),(4,'AUD-001','Rode Wireless GO II','AUDIO','Dual-channel wireless microphone kit. Includes two transmitters, one receiver and three charging cables.','Media Lab, Level 2',NULL,'READY',0,'2026-10-28 17:04:42.396216'),(5,'AUD-002','Zoom H5 Recorder','AUDIO','Portable audio recorder with an XY capsule, two XLR inputs and a memory card. Check batteries before collection.','Media Lab, Level 2',NULL,'READY',0,'2026-10-28 17:04:42.398214'),(6,'AUD-003','Shure SM58','AUDIO','Dynamic vocal microphone with a stand clip and XLR cable. Suitable for interviews and live presentations.','Performance Room, Level 1',NULL,'READY',0,'2026-10-28 17:04:42.401722'),(7,'CMP-001','Lenovo ThinkPad T14','COMPUTING','14-inch project laptop with 16 GB RAM and a 512 GB SSD. Includes the power adapter and a protective sleeve.','IT Desk, Level 1',NULL,'READY',0,'2026-10-28 17:04:42.405223'),(8,'CMP-002','Wacom Intuos Pro','COMPUTING','Medium pen tablet for illustration and design work. Includes the pen, pen stand and USB cable.','Design Studio, Level 3',NULL,'READY',0,'2026-10-28 17:04:42.407720'),(9,'LAB-001','Arduino Starter Kit','LAB','Arduino Uno with breadboard, jumper wires and basic sensors. Return all components in the original organizer.','Maker Space, Level 1',NULL,'READY',0,'2026-10-28 17:04:42.409720'),(10,'LAB-002','Digital Oscilloscope','LAB','Two-channel bench oscilloscope with probes. Temporarily unavailable while annual calibration is completed.','Electronics Lab, Level 1','5fbc6cfa-4fbe-47b3-88c8-67434eeb6f91','MAINTENANCE',1,'2026-10-28 17:04:42.412220'),(11,'ACC-001','Manfrotto Compact Tripod','ACCESSORIES','Lightweight camera tripod with a quick-release plate. Maximum supported load is 1.5 kg.','Media Lab, Level 2',NULL,'READY',0,'2026-10-28 17:04:42.414732'),(12,'ACC-002','Portable LED Light','ACCESSORIES','Bi-color LED panel with an adjustable stand and power supply. Includes a soft diffuser and carry case.','Media Lab, Level 2',NULL,'READY',0,'2026-10-28 17:04:42.418236'),(13,'VERIFY-73D1E235','Verified presentation camera','CAMERA','Camera, lens, battery and carry bag for the live workflow verification.','Media Lab, Level 2',NULL,'READY',0,'2026-11-04 17:08:25.335766'),(14,'VERIFY-663AA5F0','Verified presentation camera','CAMERA','Camera, lens, battery and carry bag for the live workflow verification.','Media Lab, Level 2',NULL,'READY',2,'2026-11-04 17:22:16.214988'),(15,'DEMO-MW2E0G1P','Campus presentation camera kit','CAMERA','Camera, lens, battery, charger and carry bag. Prepared for the campus project demonstration.','Media Lab, Level 2',NULL,'READY',0,'2026-11-04 17:25:12.688355'),(16,'VERIFY-74FA379C','Verified presentation camera','CAMERA','Camera, lens, battery and carry bag for the live workflow verification.','Media Lab, Level 2',NULL,'READY',2,'2026-11-04 17:36:24.606505'),(17,'DEMO-MW2EF8UX','Campus presentation camera kit','CAMERA','Camera, lens, battery, charger and carry bag. Prepared for the campus project demonstration.','Media Lab, Level 2',NULL,'READY',0,'2026-11-04 17:36:43.282464'),(18,'DEMO-MW2EHFGU','Campus presentation camera kit','CAMERA','Camera, lens, battery, charger and carry bag. Prepared for the campus project demonstration.','Media Lab, Level 2',NULL,'READY',0,'2026-11-04 17:38:25.096778'),(19,'VERIFY-53EF5BA0','Verified presentation camera','CAMERA','Camera, lens, battery and carry bag for the live workflow verification.','Media Lab, Level 2',NULL,'READY',2,'2026-11-04 17:44:33.390830'),(20,'DEMO-MW2Y5DDX','Campus presentation camera kit','CAMERA','Camera, lens, battery, charger and carry bag. Prepared for the campus project demonstration.','Media Lab, Level 2',NULL,'READY',2,'2026-11-05 02:49:11.646597');
