DROP TABLE IF EXISTS `notifications`;
SET @saved_cs_client     = @@character_set_client ;
SET character_set_client = utf8mb4 ;
CREATE TABLE `notifications` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `recipient_id` bigint NOT NULL,
  `reservation_id` bigint NOT NULL,
  `title` varchar(100) NOT NULL,
  `message` varchar(500) NOT NULL,
  `dedupe_key` varchar(100) NOT NULL,
  `created_at` timestamp(6) NOT NULL,
  `read_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_notification_dedupe` (`dedupe_key`),
  KEY `fk_notification_user` (`recipient_id`),
  KEY `fk_notification_reservation` (`reservation_id`),
  CONSTRAINT `fk_notification_reservation` FOREIGN KEY (`reservation_id`) REFERENCES `reservations` (`id`),
  CONSTRAINT `fk_notification_user` FOREIGN KEY (`recipient_id`) REFERENCES `app_users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
SET character_set_client = @saved_cs_client ;

DROP TABLE IF EXISTS `reservations`;
SET @saved_cs_client     = @@character_set_client ;
SET character_set_client = utf8mb4 ;
CREATE TABLE `reservations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `equipment_id` bigint NOT NULL,
  `requester_id` bigint NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `purpose` varchar(500) NOT NULL,
  `status` varchar(30) NOT NULL,
  `request_key` varchar(36) NOT NULL,
  `review_note` varchar(500) DEFAULT NULL,
  `reviewed_by_id` bigint DEFAULT NULL,
  `reviewed_at` timestamp(6) NULL DEFAULT NULL,
  `checked_out_at` timestamp(6) NULL DEFAULT NULL,
  `returned_at` timestamp(6) NULL DEFAULT NULL,
  `created_at` timestamp(6) NOT NULL,
  `version` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reservation_request` (`requester_id`,`request_key`),
  KEY `fk_reservation_reviewer` (`reviewed_by_id`),
  KEY `ix_reservation_equipment_dates` (`equipment_id`,`status`,`start_date`,`end_date`),
  KEY `ix_reservation_requester` (`requester_id`,`created_at`),
  CONSTRAINT `fk_reservation_equipment` FOREIGN KEY (`equipment_id`) REFERENCES `equipment` (`id`),
  CONSTRAINT `fk_reservation_requester` FOREIGN KEY (`requester_id`) REFERENCES `app_users` (`id`),
  CONSTRAINT `fk_reservation_reviewer` FOREIGN KEY (`reviewed_by_id`) REFERENCES `app_users` (`id`),
  CONSTRAINT `ck_reservation_dates` CHECK ((`end_date` >= `start_date`))
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
